-- Hop v1 evidence-first transfer-ID matching.
--
-- The generic bridge endpoint table routes activity to a protocol. This table
-- supplies the missing Hop identity dimensions: deployment, asset route,
-- chain direction, token variants, activation bounds, and finality policy.

CREATE TABLE IF NOT EXISTS eth_hop_bridge_routes (
  id BIGSERIAL PRIMARY KEY,
  deployment_key VARCHAR(64) NOT NULL,
  family_version VARCHAR(48) NOT NULL,
  route_key VARCHAR(128) NOT NULL,
  asset_key VARCHAR(96) NOT NULL,
  source_chain_id INTEGER NOT NULL,
  destination_chain_id INTEGER NOT NULL,
  source_bridge_address VARCHAR(42) NOT NULL,
  source_wrapper_address VARCHAR(42) NOT NULL,
  destination_bridge_address VARCHAR(42) NOT NULL,
  destination_wrapper_address VARCHAR(42),
  source_asset_addresses JSONB NOT NULL,
  destination_asset_addresses JSONB NOT NULL,
  source_token_indices JSONB NOT NULL DEFAULT '[0,1]'::jsonb,
  destination_token_indices JSONB NOT NULL DEFAULT '[0,1]'::jsonb,
  source_valid_from_block BIGINT,
  source_valid_to_block BIGINT,
  destination_valid_from_block BIGINT,
  destination_valid_to_block BIGINT,
  abi_variant VARCHAR(96) NOT NULL,
  finality_policy JSONB NOT NULL DEFAULT '{"mode":"rpc_finalized","required_on":"both_sides"}'::jsonb,
  source_url TEXT NOT NULL,
  source_commit VARCHAR(64) NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT eth_hop_route_source_bridge_check
    CHECK (source_bridge_address ~ '^0x[0-9a-f]{40}$'),
  CONSTRAINT eth_hop_route_source_wrapper_check
    CHECK (source_wrapper_address ~ '^0x[0-9a-f]{40}$'),
  CONSTRAINT eth_hop_route_destination_bridge_check
    CHECK (destination_bridge_address ~ '^0x[0-9a-f]{40}$'),
  CONSTRAINT eth_hop_route_destination_wrapper_check
    CHECK (destination_wrapper_address IS NULL OR destination_wrapper_address ~ '^0x[0-9a-f]{40}$'),
  CONSTRAINT eth_hop_route_chain_check CHECK (source_chain_id <> destination_chain_id),
  CONSTRAINT eth_hop_route_bounds_check CHECK (
    (source_valid_from_block IS NULL OR source_valid_to_block IS NULL
      OR source_valid_from_block <= source_valid_to_block)
    AND (destination_valid_from_block IS NULL OR destination_valid_to_block IS NULL
      OR destination_valid_from_block <= destination_valid_to_block)
  ),
  CONSTRAINT eth_hop_route_assets_check CHECK (
    jsonb_typeof(source_asset_addresses) = 'array'
    AND jsonb_typeof(destination_asset_addresses) = 'array'
    AND jsonb_typeof(source_token_indices) = 'array'
    AND jsonb_typeof(destination_token_indices) = 'array'
  ),
  CONSTRAINT eth_hop_route_source_check CHECK (source_url LIKE 'https://%'),
  UNIQUE (deployment_key, family_version, route_key)
);

CREATE INDEX IF NOT EXISTS idx_eth_hop_routes_source
  ON eth_hop_bridge_routes (source_chain_id, destination_chain_id, asset_key)
  WHERE enabled;

CREATE INDEX IF NOT EXISTS idx_eth_hop_routes_destination
  ON eth_hop_bridge_routes (destination_chain_id, source_chain_id, asset_key)
  WHERE enabled;

